from contextlib import asynccontextmanager
from pathlib import Path
from typing import Any

import numpy as np
import scanpy as sc
from fastapi import FastAPI, HTTPException, Query
from fastapi.responses import HTMLResponse, JSONResponse
import json

DATA_PATH = Path(__file__).parent / "ddls-week5-s1-junk-or-signal-dataset" / "data" / "pbmc3k.h5ad"


@asynccontextmanager
async def lifespan(app: FastAPI):
    if not DATA_PATH.exists():
        raise RuntimeError(f"Dataset not found: {DATA_PATH}")
    app.state.adata = sc.read_h5ad(DATA_PATH)
    yield
    del app.state.adata


app = FastAPI(title="PBMC 3K Explorer", lifespan=lifespan)


def clean(value: Any) -> Any:
    if isinstance(value, (np.integer, np.floating)):
        return value.item()
    if isinstance(value, np.ndarray):
        return value.tolist()
    return value


def expression_vector(adata, gene: str) -> np.ndarray:
    if gene not in adata.var_names:
        raise HTTPException(404, f"Unknown gene: {gene}")
    values = adata[:, gene].X
    if hasattr(values, "toarray"):
        values = values.toarray()
    return np.asarray(values).reshape(-1)


@app.get("/api/umap")
def umap(cluster: str | None = None):
    adata = app.state.adata
    coords = np.asarray(adata.obsm["X_umap"])
    mask = np.ones(adata.n_obs, dtype=bool) if cluster in (None, "all") else np.asarray(adata.obs["leiden"].astype(str) == cluster)
    if not mask.any():
        raise HTTPException(404, f"Unknown cluster: {cluster}")
    return {
        "x": coords[mask, 0].tolist(), "y": coords[mask, 1].tolist(),
        "clusters": adata.obs.loc[mask, "leiden"].astype(str).tolist(),
        "cells": adata.obs_names[mask].tolist(), "cluster": cluster or "all",
    }


@app.get("/api/genes")
def genes(search: str = Query("", max_length=100), limit: int = Query(100, ge=1, le=500)):
    names = [str(g) for g in app.state.adata.var_names if search.upper() in str(g).upper()]
    return {"genes": names[:limit], "total": len(names)}


@app.get("/api/expression/{gene}")
def expression(gene: str):
    adata = app.state.adata
    values = expression_vector(adata, gene)
    return {"gene": gene, "expression": values.tolist(), "cells": adata.obs_names.tolist(), "min": clean(values.min()), "max": clean(values.max())}


def quality_summary(adata, mask):
    quality = adata.obs.loc[mask, ["n_genes", "total_counts", "pct_mito"]]
    return {col: {"mean": clean(values.mean()), "median": clean(values.median()), "min": clean(values.min()), "max": clean(values.max())} for col in quality.columns for values in [quality[col]]}


def ranked_markers(adata, target: str, reference: str | None = None, n: int = 12):
    target_mask = np.asarray(adata.obs["leiden"].astype(str) == target)
    comparison_mask = np.ones(adata.n_obs, dtype=bool) if reference is None else np.asarray(adata.obs["leiden"].astype(str) == reference)
    target_x = adata.X[target_mask]
    comparison_x = adata.X[comparison_mask]
    if hasattr(target_x, "toarray"):
        target_x = target_x.toarray()
        comparison_x = comparison_x.toarray()
    target_x, comparison_x = np.asarray(target_x), np.asarray(comparison_x)
    target_mean, comparison_mean = target_x.mean(0), comparison_x.mean(0)
    target_fraction = (target_x > 0).mean(0)
    comparison_fraction = (comparison_x > 0).mean(0)
    score = (target_mean - comparison_mean) * (target_fraction - comparison_fraction).clip(min=0.05)
    top = np.argsort(score)[::-1][:n]
    return [{"gene": str(adata.var_names[i]), "score": clean(score[i]), "mean_expression": clean(target_mean[i]), "fraction_expressing": clean(target_fraction[i]), "comparison_mean": clean(comparison_mean[i]), "comparison_fraction": clean(comparison_fraction[i])} for i in top]


@app.get("/api/decisions")
def decisions():
    adata = app.state.adata
    return {"cluster_01": {"recommendation": "keep_separate", "reason": "Review the discriminating marker programs below before combining numbered clusters."}, "cluster_6": {"recommendation": "retain_provisionally", "reason": "PPBP/PF4 platelet-like signal is coherent, but only 13 cells makes the estimate low-confidence."}}


@app.get("/api/compare/0/1")
def compare_01(n: int = Query(12, ge=1, le=50)):
    adata = app.state.adata
    masks = {c: np.asarray(adata.obs["leiden"].astype(str) == c) for c in ("0", "1")}
    return {"recommendation": "keep_separate", "summary": {c: {"cells": int(m.sum()), "quality": quality_summary(adata, m)} for c, m in masks.items()}, "markers_0_vs_1": ranked_markers(adata, "0", "1", n), "markers_1_vs_0": ranked_markers(adata, "1", "0", n)}


@app.get("/api/clusters")
def clusters():
    adata = app.state.adata
    return {"clusters": [str(x) for x in adata.obs["leiden"].cat.categories], "counts": {str(k): int(v) for k, v in adata.obs["leiden"].value_counts().items()}}


@app.get("/api/cluster/{cluster}")
def cluster_detail(cluster: str, n: int = Query(10, ge=1, le=50)):
    adata = app.state.adata
    mask = np.asarray(adata.obs["leiden"].astype(str) == cluster)
    if not mask.any():
        raise HTTPException(404, f"Unknown cluster: {cluster}")
    x = adata.X[mask]
    if hasattr(x, "toarray"):
        x = x.toarray()
    means = np.asarray(x).mean(axis=0)
    # A compact, deterministic marker ranking: highest within-cluster mean expression.
    top = np.argsort(means)[::-1][:n]
    return {
        "cluster": cluster, "cells": int(mask.sum()),
        "markers": ranked_markers(adata, cluster, None, n),
        "quality": quality_summary(adata, mask),
        "warning": "Marker statistics are unstable because this cluster contains fewer than 20 cells." if mask.sum() < 20 else None,
    }


@app.get("/api/analysis/cluster-0-vs-1")
def cluster_analysis():
    analysis_path = Path(__file__).parent / "cluster_0_vs_1_analysis.json"
    if not analysis_path.exists():
        raise HTTPException(404, "Analysis has not been generated yet")
    return JSONResponse(json.loads(analysis_path.read_text()))


@app.get("/", response_class=HTMLResponse)
def index():
    return HTMLResponse(INDEX_HTML)


